/**
 * The words of each moment. Every sentence is one `t()` key with its
 * placeholders; a headword is set in its own language (`Bilingual`, with its
 * own direction) and the sentence around it follows the interface. Nothing
 * is glued from fragments.
 */
import type { LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import type { IconName } from '@/components/ui/Icon.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { trialDate } from '@/features/billing/trial.js';
import { STREAK_YEAR, type Moment } from './moments.js';

/** Numbers as the interface writes them: 1,000 rather than 1000. */
export function formatCount(value: number): string {
  return value.toLocaleString('en-US');
}

/** What a moment says: a title for the big ones, a line for all, and its mark. */
export interface MomentCopy {
  title?: React.ReactNode;
  /** The same title as plain text, for the live region and the sheet's name. */
  titleText?: string;
  line: React.ReactNode;
  lineText: string;
  icon: IconName | 'boxes';
}

/** A key's sentence with `{headword}` set in the word's own language. */
function withWord(
  key: MessageKey,
  vars: Record<string, string | number>,
  headword: string | undefined,
  lang: LanguageCode,
): { node: React.ReactNode; text: string } {
  const template = t(key, vars);
  if (headword === undefined || !template.includes('{headword}')) return { node: template, text: template };
  const [before = '', after = ''] = template.split('{headword}');
  return {
    node: (
      <>
        {before}
        <Bilingual lang={lang}>{headword}</Bilingual>
        {after}
      </>
    ),
    text: `${before}${headword}${after}`,
  };
}

/** The weekday a day index falls on, as the week strip reads day indices. */
function weekday(day: number): string {
  return new Date(day * 86_400_000).toLocaleDateString('en-US', { weekday: 'long', timeZone: 'UTC' });
}

/** The line under "N days in a row", by the value. */
function streakLine(count: number): { key: MessageKey; vars: Record<string, number> } {
  const known: Partial<Record<number, MessageKey>> = {
    7: 'celebrate.streak7',
    14: 'celebrate.streak14',
    30: 'celebrate.streak30',
    50: 'celebrate.streak50',
    100: 'celebrate.streak100',
    200: 'celebrate.streak200',
    365: 'celebrate.streak365',
  };
  const key = known[count];
  if (key !== undefined) return { key, vars: {} };
  return { key: 'celebrate.streakYears', vars: { count: Math.floor(count / STREAK_YEAR) } };
}

/**
 * The words for one moment. `langOf` says which language a word's notebook
 * learns, so a Persian headword reads right to left inside an English line.
 */
export function momentCopy(
  moment: Moment,
  langOf: (notebookId: string) => LanguageCode,
  now: Date = new Date(),
): MomentCopy {
  const headword = moment.word?.headword;
  const lang = moment.word === undefined ? 'en' : langOf(moment.word.notebookId);
  const line = (
    key: MessageKey,
    vars: Record<string, string | number> = {},
  ): Pick<MomentCopy, 'line' | 'lineText'> => {
    const filled = withWord(key, vars, headword, lang);
    return { line: filled.node, lineText: filled.text };
  };
  const title = (
    key: MessageKey,
    vars: Record<string, string | number> = {},
  ): Pick<MomentCopy, 'title' | 'titleText'> => {
    const filled = withWord(key, vars, headword, lang);
    return { title: filled.node, titleText: filled.text };
  };
  const count = moment.count ?? 0;

  switch (moment.id) {
    case 'firstSession': {
      const which =
        moment.variant === 'right'
          ? line('celebrate.firstSessionRight', { box: moment.box ?? 2 })
          : moment.variant === 'missed'
            ? line('celebrate.firstSessionMissed')
            : moment.variant === 'many'
              ? line('celebrate.firstSessionMany', { count })
              : line('celebrate.firstSessionManyLater', { count });
      return { ...title('celebrate.firstSessionTitle'), ...which, icon: 'sparkles' };
    }
    case 'firstRecall':
      return { ...line('celebrate.recall', { count }), icon: 'sparkles' };
    case 'streak3':
      return { ...line('celebrate.streak3'), icon: 'flame' };
    case 'streak7':
    case 'streakMid':
    case 'streakBig': {
      const below = streakLine(count);
      return {
        ...title('celebrate.streakTitle', { count: formatCount(count) }),
        ...line(below.key, below.vars),
        icon: 'flame',
      };
    }
    case 'firstMastered':
      return {
        ...title('celebrate.firstMasteredTitle'),
        ...line('celebrate.firstMastered', { days: moment.days ?? 0 }),
        icon: 'boxes',
      };
    case 'allDone':
      return { ...line('celebrate.allDone'), icon: 'check' };
    case 'words':
      return {
        ...title('celebrate.wordsTitle', { count: formatCount(count) }),
        ...line('celebrate.words'),
        icon: 'notebook',
      };
    case 'comeback':
      return { ...line('celebrate.comeback', { count }), icon: 'sparkles' };
    case 'mastered':
      return {
        ...title('celebrate.masteredTitle', { count: formatCount(count) }),
        ...line('celebrate.mastered'),
        icon: 'boxes',
      };
    case 'streakBest':
      return {
        ...title('celebrate.bestTitle'),
        ...line('celebrate.best', { count, previous: moment.previous ?? 0 }),
        icon: 'flame',
      };
    case 'freezeSaved':
      return { ...line('celebrate.freezeSaved', { day: weekday(moment.day ?? 0), count }), icon: 'flame' };
    case 'slipBeaten':
      return moment.word === undefined
        ? { ...line('celebrate.slipBeatenMany', { count }), icon: 'sparkles' }
        : { ...line('celebrate.slipBeaten'), icon: 'sparkles' };
    case 'busiest':
      return { ...line('celebrate.busiest', { count }), icon: 'sparkles' };
    case 'trialStart':
      return {
        ...title('celebrate.trialTitle', {
          date: trialDate(new Date(moment.endsAt ?? now.toISOString()), now),
        }),
        ...line('celebrate.trial'),
        icon: 'sparkles',
      };
    case 'anniversary':
      return { ...line('celebrate.anniversary', { count }), icon: 'sparkles' };
  }
}
